window.FEATURES = [
  {
    id: "netfx",
    n: {
      en: ".NET Framework 2/3/4 — Enable",
      es: ".NET Framework 2/3/4 — Activar",
    },
    enable:
      'dism /online /enable-feature /featurename:NetFx3 /all /quiet /norestart; Write-Host "[OK] .NET Framework enabled"',
  },
  {
    id: "hyperv",
    n: { en: "Hyper-V — Enable", es: "Hyper-V — Activar" },
    enable:
      'dism /online /enable-feature /featurename:Microsoft-Hyper-V-All /all /quiet /norestart; Write-Host "[OK] Hyper-V enabled"',
  },
  {
    id: "f8disable",
    n: {
      en: "Legacy F8 Boot Recovery — Disable",
      es: "Legacy F8 Boot Recovery — Desactivar",
    },
    enable:
      'bcdedit /set {default} bootmenupolicy standard; Write-Host "[OK] F8 legacy disabled"',
  },
  {
    id: "f8enable",
    n: {
      en: "Legacy F8 Boot Recovery — Enable",
      es: "Legacy F8 Boot Recovery — Activar",
    },
    enable:
      'bcdedit /set {default} bootmenupolicy legacy; Write-Host "[OK] F8 legacy enabled"',
  },
  {
    id: "legacymedia",
    n: {
      en: "Legacy Media (WMP, DirectPlay) — Enable",
      es: "Legacy Media (WMP, DirectPlay) — Activar",
    },
    enable:
      'dism /online /enable-feature /featurename:WindowsMediaPlayer /all /quiet /norestart; dism /online /enable-feature /featurename:DirectPlay /all /quiet /norestart; Write-Host "[OK] Legacy media enabled"',
  },
  {
    id: "nfs",
    n: {
      en: "Network File System (NFS) — Enable",
      es: "Network File System (NFS) — Activar",
    },
    enable:
      'dism /online /enable-feature /featurename:ServicesForNFS-ClientOnly /all /quiet /norestart; dism /online /enable-feature /featurename:ClientForNFS-Infrastructure /all /quiet /norestart; Write-Host "[OK] NFS enabled"',
  },
  {
    id: "regbackupsched",
    n: {
      en: "Registry Backup (Daily 12:30am) — Enable",
      es: "Registry Backup (Diario 00:30) — Activar",
    },
    enable: `$dir = "$env:SystemDrive\\RegistryBackup"; New-Item -ItemType Directory -Path $dir -Force -ErrorAction SilentlyContinue | Out-Null; $action = New-ScheduledTaskAction -Execute "powershell.exe" -Argument "-Command reg export HKLM '$dir\\HKLM_$(Get-Date -Format yyyyMMdd_HHmmss).reg' /y"; $trigger = New-ScheduledTaskTrigger -Daily -At 00:30; Register-ScheduledTask -TaskName "CodeWinOptimizer_RegistryBackup" -Action $action -Trigger $trigger -Force -ErrorAction Stop | Out-Null; Write-Host "[OK] Daily registry backup scheduled at 00:30"`,
  },
  {
    id: "sandbox",
    n: { en: "Windows Sandbox — Enable", es: "Windows Sandbox — Activar" },
    enable:
      'dism /online /enable-feature /featurename:Containers-DisposableClientVM /all /quiet /norestart; Write-Host "[OK] Windows Sandbox enabled"',
  },
  {
    id: "wsl",
    n: { en: "WSL — Enable", es: "WSL — Activar" },
    enable:
      'dism /online /enable-feature /featurename:Microsoft-Windows-Subsystem-Linux /all /quiet /norestart; dism /online /enable-feature /featurename:VirtualMachinePlatform /all /quiet /norestart; Write-Host "[OK] WSL enabled"',
  },
];

window.FIXES = [
  {
    id: "autologin",
    n: { en: "Autologin — Enable", es: "Autologin — Activar" },
    cmd: `
$regPath = "HKLM\\SOFTWARE\\Microsoft\\Windows NT\\CurrentVersion\\Winlogon"
$user = (Get-CimInstance -Class Win32_ComputerSystem | Select-Object -ExpandProperty Username)
Set-ItemProperty -Path $regPath -Name "AutoAdminLogon" -Value "1" -Force
Set-ItemProperty -Path $regPath -Name "DefaultUserName" -Value $user -Force
Set-ItemProperty -Path $regPath -Name "DefaultPassword" -Value "" -Force
Write-Host "Autologin enabled for $user"`,
  },
  {
    id: "netreset",
    n: { en: "Network — Reset", es: "Red — Reiniciar" },
    cmd: 'netsh int ip reset; netsh winsock reset; ipconfig /flushdns; Write-Host "Network stack reset complete"',
  },
  {
    id: "ntp",
    n: { en: "NTP Server — Enable", es: "Servidor NTP — Activar" },
    cmd: 'w32tm /config /syncfromflags:manual /manualpeerlist:"time.windows.com" /reliable:YES /update; net stop w32time; net start w32time; w32tm /resync /force; Write-Host "NTP sync enabled"',
  },
  {
    id: "sfc",
    n: {
      en: "System Corruption Scan — Run",
      es: "Escaneo Corrupcion — Ejecutar",
    },
    cmd: 'DISM /Online /Cleanup-Image /RestoreHealth; sfc /scannow; Write-Host "System scan complete"',
  },
  {
    id: "wureset",
    n: { en: "Windows Update — Reset", es: "Windows Update — Reiniciar" },
    cmd: 'net stop wuauserv; net stop cryptSvc; net stop bits; net stop msiserver; Remove-Item -Recurse -Force "$env:windir\\SoftwareDistribution" -ErrorAction SilentlyContinue; net start wuauserv; net start cryptSvc; net start bits; net start msiserver; Write-Host "Windows Update cache reset"',
  },
  {
    id: "wingetre",
    n: { en: "WinGet — Reinstall", es: "WinGet — Reinstalar" },
    cmd: 'Write-Host "Reinstalling WinGet..."; try{Add-AppxPackage -RegisterByFamilyName -MainPackage Microsoft.DesktopAppInstaller_8wekyb3d8bbwe -ErrorAction Stop; Write-Host "WinGet reinstalled successfully"}catch{Write-Host "ERR: WinGet reinstall failed — $($_.Exception.Message)"}',
  },
];
